import React from "react";
import { Link, useLocation } from "react-router-dom";

function NavBar() {
  const location = useLocation();

  const isHome = location.pathname === "/";
  const isCreate = location.pathname === "/create" || location.pathname === "/create-campaign";

  return (
    <nav className="navbar">
      <div className="navbar-brand">
        <Link to="/">
          <span className="brand-icon">🌱</span>
          <span className="brand-text">Crowdfunding Platform</span>
        </Link>
      </div>

      <div className="navbar-links">
        <Link to="/" className={isHome ? "active" : ""}>
          Home
        </Link>

        <Link to="/create-campaign" className={isCreate ? "active" : ""}>
          Create Campaign
        </Link>
      </div>
    </nav>
  );
}

export default NavBar;
